                vm.set("total", total);

                refs.total.setHtml(total.toLocaleString('ko-KR') + '건');
                refs.searchTotal.setHtml('검색결과 <span style="color:#CB2B11">' + total.toLocaleString('ko-KR') + '</span>건');

